public class Solution {
    public String splitLoopedString(String[] strs) {
        return computeMaxSubstring(strs);
    }

    private String computeMaxSubstring(String[] strs) {
        String ans = "", cur = "";
        for (String s : strs) {
            String rev = new StringBuilder(s).reverse().toString();
            cur += (s.compareTo(rev) > 0) ? s : rev;
        }

        return computeMaxSubstring(cur);
    }

    private String computeMaxSubstring(String str) {
        String ans = "", maxSubstr = "";

        for (int i = 0; i < str.length(); i++) {
            // Check if the substring starting at index i is greater than current maximum
            String subStr = str.substring(i);

            // Reverse and check if it's greater
            String revSubStr = new StringBuilder(subStr).reverse().toString();
            maxSubstr = (subStr.compareTo(revSubStr) > 0) ? subStr : revSubStr;
        }

        return ans + maxSubstr;
    }

}

