        for (int i = 0; i < 4; i++) {
            for (int j = i + 1; j < 4; j++) {
                dist.add((points[i][0] - points[j][0]) * (points[i][0] - points[j][0]) + (points[i][1] - points[j][1]) * (points[i][1] - points[j][1]));
