public class Solution {
    public boolean validSquare(int[] p1, int[] p2, int[] p3, int[] p4) {
        Set<Integer> dist = new HashSet<>();
        int[][] points = {p1, p2, p3, p4};

        for (int i = 0; i < 4; i++) {
            for (int j = i + 1; j < 4; j++) {
                dist.add((points[i][0] - points[j][0]) * (points[i][0] - points[j][0]) + (points[i][1] - points[j][1]) * (points[i][1] - points[j][1]));
            }
        }

        return computeValidSquare(dist);
    }

  private boolean computeValidSquare(Set<Integer> dist) {
      // Helper method to compute the validity of a square based on given distances.
      if (dist.size() == 2 && !dist.contains(0)) {
          int side = Math.min(dist.toArray(new Integer[0])[0], dist.toArray(new Integer[0])[1]);
          return dist.stream().filter(d -> d != side * side).count() == 4;
      }
      return false;
    }

}

