public class Solution {
    public void duplicateZeros(int[] array) {
        int n = array.length;
        for (int i = 0; i < n - 1; ++i) {
            if (array[i] == 0) {
                for (int j = n - 1; j > i + 1; --j) {
                    array[j] = array[j - 1];
                }
                array[++i] = 0;
            }
        }
    }
}

